import React, { useState } from 'react';
import './Capabilities.css';
const panels = {Overview:[42,68,55,83,74,96],Retention:[80,75,73,69,65,63],Acquisition:[22,32,56,48,72,91]};
type Panel = keyof typeof panels;
export default function Capabilities(){const [active,setActive]=useState<Panel>('Overview');const labels=Object.keys(panels) as Panel[];
 return <section id="capabilities" className="f-capabilities"><div className="f-section-title"><span className="eyebrow">01 / A SHARED PERSPECTIVE</span><h2>A better question<br />changes the picture.</h2><p>Explore the sample views below. Every value is illustrative, with a table alternative for the chart.</p></div><div className="f-console"><div className="f-console-top"><span>FIELDWORK / SAMPLE DATA</span><span>LOCAL DEMO ●</span></div><div role="tablist" aria-label="Analytics views" className="f-tabs">{labels.map((label,index)=><button key={label} id={'tab-'+label} role="tab" aria-controls="analytics-panel" aria-selected={active===label} tabIndex={active===label?0:-1} onClick={()=>setActive('Overview')} onKeyDown={event=>{let next=index;if(event.key==='ArrowRight')next=(index+1)%labels.length;else if(event.key==='ArrowLeft')next=(index+labels.length-1)%labels.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=labels.length-1;else return;event.preventDefault();setActive(labels[next]);document.getElementById('tab-'+labels[next])?.focus();}}>{label}</button>)}</div><div id="analytics-panel" role="tabpanel" aria-labelledby={'tab-'+active} tabIndex={0}><div className="f-chart-title"><h3>{active}</h3><span>INDEX / ILLUSTRATIVE</span></div><div className="f-bars" aria-hidden="true">{panels[active].map((value,index)=><div key={index}><i style={{height:value+'%'}}/><span>{['Jan','Feb','Mar','Apr','May','Jun'][index]}</span></div>)}</div><details><summary>View sample data as a table</summary><table><caption>{active} sample values</caption><thead><tr><th scope="col">Month</th><th scope="col">Index</th></tr></thead><tbody>{panels[active].map((value,index)=><tr key={index}><th scope="row">{['Jan','Feb','Mar','Apr','May','Jun'][index]}</th><td>{value}</td></tr>)}</tbody></table></details></div></div></section>;
}

</file>
